from google.cloud import firestore

class MessageAuditStore:
    def __init__(self, project_id: str, collection_name: str = "message_audits"):
        self.db = firestore.Client(project=project_id)
        self.collection_ref = self.db.collection(collection_name)

    def save_message(self, message_id: str, message_content: dict):
        doc_ref = self.collection_ref.document(message_id)
        doc_ref.set(message_content)
        return True

    def get_message(self, message_id: str):
        doc_ref = self.collection_ref.document(message_id)
        doc = doc_ref.get()
        if doc.exists:
            return doc.to_dict()
        else:
            return None

import google.generativeai as genai
import os

def check_unsafe_content(text: str) -> dict:
    """
    Checks message payload text for unsafe content using Google's generative AI model.

    Args:
        text: The text content to check.

    Returns:
        A dictionary indicating if the content is safe and any safety ratings.
    """
    try:
        genai.configure(api_key=os.environ["GOOGLE_API_KEY"])
    except KeyError:
        return {"error": "GOOGLE_API_KEY environment variable not set."}

    model = genai.GenerativeModel('gemini-pro')

    safety_settings = [
        {"category": "HARM_CATEGORY_HARASSMENT", "threshold": "BLOCK_MEDIUM_AND_ABOVE"},
        {"category": "HARM_CATEGORY_HATE_SPEECH", "threshold": "BLOCK_MEDIUM_AND_ABOVE"},
        {"category": "HARM_CATEGORY_SEXUALLY_EXPLICIT", "threshold": "BLOCK_MEDIUM_AND_ABOVE"},
        {"category": "HARM_CATEGORY_DANGEROUS_CONTENT", "threshold": "BLOCK_MEDIUM_AND_ABOVE"},
    ]

    try:
        response = model.generate_content(
            text,
            safety_settings=safety_settings
        )

        if not response._result.prompt_feedback.safety_ratings:
            return {"is_safe": True, "safety_ratings": []}

        for rating in response._result.prompt_feedback.safety_ratings:
            if rating.blocked:
                return {"is_safe": False, "safety_ratings": [str(rating)]}
        return {"is_safe": True, "safety_ratings": [str(r) for r in response._result.prompt_feedback.safety_ratings]}

    except Exception as e:
        return {"error": f"An error occurred: {e}"}

import json
from typing import Dict, Any, Optional

class PublishRequest:
    """
    Represents a request to publish a message to Google Cloud Pub/Sub.
    """
    def __init__(self, data: Dict[str, Any], attributes: Optional[Dict[str, str]] = None):
        self.data = json.dumps(data).encode("utf-8")
        self.attributes = attributes if attributes is not None else {}

    def to_dict(self) -> Dict[str, Any]:
        return {
            "data": self.data.decode("utf-8"),
            "attributes": self.attributes
        }

class PubsubMessage:
    """
    Represents a message received from Google Cloud Pub/Sub.
    """
    def __init__(self, message_id: str, data: bytes, attributes: Dict[str, str], publish_time: str):
        self.message_id = message_id
        self.data = data
        self.attributes = attributes
        self.publish_time = publish_time

    def get_data_as_json(self) -> Dict[str, Any]:
        return json.loads(self.data.decode("utf-8"))

    def to_dict(self) -> Dict[str, Any]:
        return {
            "message_id": self.message_id,
            "data": self.data.decode("utf-8"),
            "attributes": self.attributes,
            "publish_time": self.publish_time
        }

def normalize_message(message: PubsubMessage) -> Dict[str, Any]:
    """
    Normalizes a PubsubMessage into a common dictionary format.
    """
    normalized = {
        "id": message.message_id,
        "payload": message.get_data_as_json(),
        "metadata": message.attributes,
        "timestamp": message.publish_time
    }
    return normalized

from google.cloud import pubsub_v1
import os

class PubSubMessagingClient:
    def __init__(self, project_id: str = None):
        self.project_id = project_id if project_id else os.getenv("GOOGLE_CLOUD_PROJECT")
        if not self.project_id:
            raise ValueError("Google Cloud Project ID must be provided or set in GOOGLE_CLOUD_PROJECT environment variable.")
        self.publisher = pubsub_v1.PublisherClient()
        self.subscriber = pubsub_v1.SubscriberClient()

    def get_topic_path(self, topic_name: str):
        return self.publisher.topic_path(self.project_id, topic_name)

    def get_subscription_path(self, subscription_name: str):
        return self.subscriber.subscription_path(self.project_id, subscription_name)

    def publish_message(self, topic_name: str, data: str, **attrs):
        topic_path = self.get_topic_path(topic_name)
        data = data.encode("utf-8")
        future = self.publisher.publish(topic_path, data, **attrs)
        return future.result()

    def subscribe_message(self, subscription_name: str, callback):
        subscription_path = self.get_subscription_path(subscription_name)
        streaming_pull_future = self.subscriber.subscribe(subscription_path, callback=callback)
        print(f"Listening for messages on {subscription_path}")
        return streaming_pull_future

    def create_topic(self, topic_name: str):
        topic_path = self.get_topic_path(topic_name)
        topic = self.publisher.create_topic(request={"name": topic_path})
        print(f"Topic created: {topic.name}")
        return topic

    def create_subscription(self, topic_name: str, subscription_name: str):
        topic_path = self.get_topic_path(topic_name)
        subscription_path = self.get_subscription_path(subscription_name)
        subscription = self.subscriber.create_subscription(request={"name": subscription_path, "topic": topic_path})
        print(f"Subscription created: {subscription.name}")
        return subscription
